import heapq

def match(orders):
    book = {}          # id -> {'side':..., 'price':..., 'qty':..., 'active':bool}
    buy_heap = []       # entries: (-price, seq, id)
    sell_heap = []       # entries: (price, seq, id)
    seq = 0
    trades = []

    def clean(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            info = book.get(oid)
            if info is None or (not info['active']) or info['qty'] <= 0:
                heapq.heappop(heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
            while remaining > 0:
                clean(opp_heap)
                if not opp_heap:
                    break
                p, s, oid2 = opp_heap[0]
                if typ != 'market' and p > price:
                    break
                o = book[oid2]
                trade_qty = min(remaining, o['qty'])
                trades.append([oid, oid2, p, trade_qty])
                remaining -= trade_qty
                o['qty'] -= trade_qty
                if o['qty'] == 0:
                    o['active'] = False
                    heapq.heappop(opp_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'active': True}
                heapq.heappush(buy_heap, (-price, seq, oid))
                seq += 1

        else:  # sell
            opp_heap = buy_heap
            while remaining > 0:
                clean(opp_heap)
                if not opp_heap:
                    break
                negp, s, oid2 = opp_heap[0]
                p = -negp
                if typ != 'market' and p < price:
                    break
                o = book[oid2]
                trade_qty = min(remaining, o['qty'])
                trades.append([oid2, oid, p, trade_qty])
                remaining -= trade_qty
                o['qty'] -= trade_qty
                if o['qty'] == 0:
                    o['active'] = False
                    heapq.heappop(opp_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'active': True}
                heapq.heappush(sell_heap, (price, seq, oid))
                seq += 1

    return trades

